<template>
  <div class="login">
    <!-- 顶部 -->
    <van-nav-bar title="会员登录" left-arrow @click-left="$router.back()"></van-nav-bar>
     <!-- 主体 -->
   <div class="container">
      <div class="title">
        <h3>手机号登录</h3>
        <p>未注册的手机号登录后将自动注册</p>
      </div>

      <div class="form">
        <div class="form-item">
          <input v-model="mobil" class="inp" maxlength="11" placeholder="请输入手机号码" type="text">
        </div>
        <div class="form-item">
          <input v-model="picCode" class="inp" maxlength="5" placeholder="请输入图形验证码" type="text">
          <img v-if="picUrl" :src="picUrl" @click="getPicCode" alt="">
        </div>
        <div class="form-item">
          <input v-model="msgCode" class="inp" placeholder="请输入短信验证码" type="text">
          <button @click="getCode">
            {{ second===totalSecond?'获取短信验证码':second+'秒后获取' }}
          </button>
        </div>
      </div>

      <div @click="codeLogin" class="login-btn">登录</div>
    </div>
</div>
</template>

<script>
import { codeLogin, getMsgCode, getpicCode } from '@/api/login'
export default {
  name: 'LoginIndex',
  data () {
    return {
      picCode: '', // 用户输入的图形验证码
      picKey: '', // 将来请求传递的图形验证码标识
      picUrl: '', // 用于渲染图片
      totalSecond: 60, // 总倒计时秒数
      second: 60, // 当前秒数用于second--
      timer: null,
      mobil: '', // 手机验证码
      msgCode: ''// 短信验证码
    }
  },
  async created () {
    this.getPicCode()
  },
  methods: {
    async getPicCode () {
      const { data: { base64, key } } = await getpicCode()
      this.picUrl = base64
      this.picKey = key
      // this.$toast('获取验证码成功')
    },
    // 校验手机号和图形验证码是否合法
    vaidfn () {
      if (!/^1(3[0-9]|4[01456879]|5[0-35-9]|6[2567]|7[0-8]|8[0-9]|9[0-35-9])\d{8}$/.test(this.mobil)) {
        this.$toast('请输入正确的手机号')
        return false
      }
      if (!/^\w{4}$/.test(this.picCode)) {
        this.$toast('请输入正确的验证码')
        return false
      }
      return true
    },
    async getCode () {
      if (!this.vaidfn()) {
        return
      }
      // 当前目前没有定时器开着并且totalsecond=second时才可以倒计时
      if (!this.timer && this.totalSecond === this.second) {
        // 在开启倒计时前获取短信验证码
        await getMsgCode(this.picCode, this.picKey, this.mobil)
        this.$toast('获取验证码成功，注意查收')

        // 开启倒计时
        this.timer = setInterval(() => {
          this.second--
          if (this.second <= 0) {
            clearInterval(this.timer)
            this.timer = null // 重置
            this.second = this.totalSecond // 归位
          }
        }, 1000)
      }
    },
    async codeLogin () {
      if (!this.vaidfn()) {
        return
      }
      if (!/^\d{6}$/.test(this.msgCode)) {
        this.$toast('请输入正确的短信验证码')
        return
      }
      const res = await codeLogin(this.mobil, this.msgCode)
      this.$store.commit('user/setUserInfo', res.data)
      console.log(res)
      this.$toast('恭喜登录成功')

      // 进行判断，看地址栏有无回调地址
      // 如果有--说明是其他页面，拦截到登录来的，需要回跳
      // 如果没有--正常去首页
      const url = this.$route.query.backUrl || '/'
      this.$router.replace(url)
    }
  },

  // 离开页面倒计时停止
  destroyed () {
    clearInterval(this.timer)
  }

}
</script>

<style lang="less" scoped>
.container {
  padding: 49px 29px;

  .title {
    margin-bottom: 20px;
    h3 {
      font-size: 26px;
      font-weight: normal;
    }
    p {
      line-height: 40px;
      font-size: 14px;
      color: #b8b8b8;
    }
  }

  .form-item {
    border-bottom: 1px solid #f3f1f2;
    padding: 8px;
    margin-bottom: 14px;
    display: flex;
    align-items: center;
    .inp {
      display: block;
      border: none;
      outline: none;
      height: 32px;
      font-size: 14px;
      flex: 1;
    }
    img {
      width: 94px;
      height: 31px;
    }
    button {
      height: 31px;
      border: none;
      font-size: 13px;
      color: #cea26a;
      background-color: transparent;
      padding-right: 9px;
    }
  }

  .login-btn {
    width: 100%;
    height: 42px;
    margin-top: 39px;
    background: linear-gradient(90deg,#ecb53c,#ff9211);
    color: #fff;
    border-radius: 39px;
    box-shadow: 0 10px 20px 0 rgba(0,0,0,.1);
    letter-spacing: 2px;
    display: flex;
    justify-content: center;
    align-items: center;
  }
}
</style>
